<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>搜索结果 - 畅行旅行</title>
    <style>
        body{font-family:Arial,Helvetica,sans-serif;margin:0;padding:0;background:#f5f5f5;color:#333;}
        header{background:#0066cc;color:#fff;padding:20px;text-align:center;}
        header h1{margin:0;font-size:2em;}
        nav{background:#004c99;padding:10px;}
        nav a{color:#fff;margin:0 15px;text-decoration:none;font-weight:bold;}
        .container{max-width:1200px;margin:auto;padding:20px;}
        .hotel-list{display:flex;flex-wrap:wrap;gap:20px;}
        .hotel-card{background:#fff;padding:15px;border-radius:8px;box-shadow:0 2px 5px rgba(0,0,0,0.1);flex:1 1 calc(33% - 40px);min-width:260px;}
        .hotel-card img{width:100%;height:150px;object-fit:cover;border-radius:4px;background:#ddd;}
        .hotel-card h3{margin:10px 0 5px;}
        .hotel-card p{margin:5px 0;}
        .hotel-card .price{color:#d9534f;font-weight:bold;margin-top:10px;}
        .hotel-card a{display:inline-block;margin-top:10px;padding:8px 12px;background:#0066cc;color:#fff;border-radius:4px;text-decoration:none;}
        .hotel-card a:hover{background:#004c99;}
        footer{background:#333;color:#fff;text-align:center;padding:15px;margin-top:40px;}
        @media (max-width:768px){
            .hotel-card{flex:1 1 calc(50% - 40px);}
        }
        @media (max-width:480px){
            .hotel-card{flex:1 1 100%;}
        }
    </style>
</head>
<body>
<header>
    <h1>畅行旅行 - 搜索结果</h1>
</header>
<nav>
    <a href="index.html">首页</a>
    <a href="about.html">关于我们</a>
</nav>
<div class="container">
    <h2 id="heading"></h2>
    <div class="hotel-list" id="list"></div>
</div>
<footer>
    © 2026 畅行旅行
</footer>
<script>
    // 模拟酒店数据
    const hotels = [
        {id:1, name:"北京皇家大饭店", city:"北京", price:698, img:"", desc:"位于市中心，步行可至故宫，设施齐全。"},
        {id:2, name:"三亚海滨度假村", city:"三亚", price:1188, img:"", desc:"海景房，私人沙滩，适合家庭度假。"},
        {id:3, name:"黄山云海山庄", city:"黄山", price:520, img:"", desc:"靠近黄山风景区，提供登山配套。"},
        {id:4, name:"成都锦江宾馆", city:"成都", price:399, img:"", desc:"紧邻春熙路，享受川菜美食。"},
        {id:5, name:"西安古城客栈", city:"西安", price:450, img:"", desc:"古城墙旁，体验唐代风情。"},
        {id:6, name:"桂林漓江度假屋", city:"桂林", price:750, img:"", desc:"临江而建，山水画卷尽收眼底。"}
    ];

    function getQuery() {
        const params = new URLSearchParams(location.search);
        return {
            dest: params.get('dest')||'',
            start: params.get('start')||'',
            end: params.get('end')||''
        };
    }

    function render() {
        const q = getQuery();
        const heading = document.getElementById('heading');
        heading.textContent = `目的地：“${q.dest}” 的搜索结果（${q.start} 至 ${q.end}）`;

        const list = document.getElementById('list');
        const filtered = hotels.filter(h => h.city.includes(q.dest));
        if (filtered.length===0){
            list.innerHTML = "<p>暂无符合条件的酒店，建议更换搜索关键词。</p>";
            return;
        }
        list.innerHTML = filtered.map(h => `
            <div class="hotel-card">
                <img src="data:image/svg+xml;base64,${btoa('<svg xmlns="http://www.w3.org/2000/svg" width="300" height="150"><rect width="300" height="150" fill="#ddd"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" fill="#aaa" font-size="20">酒店图片</text></svg>')}" alt="${h.name}">
                <h3>${h.name}</h3>
                <p>${h.desc}</p>
                <p class="price">¥${h.price}/晚</p>
                <a href="hotel.html?id=${h.id}">查看详情</a>
            </div>
        `).join('');
    }
    render();
</script>
</html>

