        .booking-form button:hover{background:#004c99;}
        .summary{margin-top:20px;padding:15px;background:#e9f5ff;border-radius:6px;}
        footer{background:#333;color:#fff;text-align:center;padding:15px;margin-top:40px;}
    </style>
</head>
<body>
<header>
    <h1>预订酒店</h1>
</header>
<nav>
    <a href="index.html">首页</a>
    <a href="results.html">搜索结果</a>
</nav>
<div class="container">
    <div class="booking-form">
        <h2 id="hotelName"></h2>
        <form id="bookingForm" onsubmit="return false;">
            <label for="checkin">入住日期</label>
            <input type="date" id="checkin" required>

            <label for="checkout">离店日期</label>
            <input type="date" id="checkout" required>

            <label for="roomType">房型</label>
            <select id="roomType">
                <option value="标准间">标准间</option>
                <option value="大床房">大床房</option>
                <option value="套房">套房</option>
            </select>

            <label for="guestName">客人姓名</label>
            <input type="text" id="guestName" placeholder="请输入姓名" required>

            <label for="phone">联系电话</label>
            <input type="tel" id="phone" placeholder="例如：13800138000" required>

            <label for="email">电子邮件</label>
            <input type="email" id="email" placeholder="example@domain.com" required>

            <button type="submit" onclick="calculate()">提交预订（仅演示）</button>
        </form>
        <div class="summary" id="summary" style="display:none;">
            <p><strong>预订信息：</strong></p>
            <p id="sumInfo"></p>
            <p><strong>预计总价：</strong> <span id="totalPrice"></span> 元</p>
        </div>
    </div>
</div>
<footer>
    © 2026 畅行旅行
</footer>
<script>
    const hotels = [
        {id:1, name:"北京皇家大饭店", price:698},
        {id:2, name:"三亚海滨度假村", price:1188},
        {id:3, name:"黄山云海山庄", price:520},
        {id:4, name:"成都锦江宾馆", price:399},
        {id:5, name:"西安古城客栈", price:450},
        {id:6, name:"桂林漓江度假屋", price:750}
    ];
    function getId(){
        const params = new URLSearchParams(location.search);
        return Number(params.get('id'));
    }
    function init(){
        const id = getId();
        const hotel = hotels.find(h=>h.id===id);
        if(hotel){
            document.getElementById('hotelName').textContent = `${hotel.name}（¥${hotel.price}/晚）`;
            window.currentHotel = hotel;
        }else{
            document.getElementById('hotelName').textContent = "未知酒店";
        }
    }
    function calculate(){
        const checkin = document.getElementById('checkin').value;
        const checkout = document.getElementById('checkout').value;
        if(!checkin || !checkout || checkin>=checkout){
            alert('请确保入住日期早于离店日期。');
            return;
        }
        const days = (new Date(checkout)-new Date(checkin))/ (1000*60*60*24);
        const roomType = document.getElementById('roomType').value;
        const guestName = document.getElementById('guestName').value;
        const phone = document.getElementById('phone').value;
        const email = document.getElementById('email').value;
        const basePrice = window.currentHotel.price;
        const total = basePrice * days;
        document.getElementById('sumInfo').innerHTML = `
            酒店：${window.currentHotel.name}<br>
            入住：${checkin}<br>
            离店：${checkout}<br>
            房型：${roomType}<br>
            客人：${guestName}<br>
            电话：${phone}<br>
            邮箱：${email}<br>
            天数：${days} 晚
        `;
        document.getElementById('totalPrice').textContent = total.toFixed(2);
        document.getElementById('summary').style.display = 'block';
    }
    init();
</script>
</html>

